day13Visits.push({"who": "교대 전 휴게소 직원", "time": "01:25", "dialogue": [["교대 전 휴게소 직원", "오늘은 교대가 늦어져서 저녁을 제대로 못 먹었어요."], ["교대 전 휴게소 직원", "게이트 라이트 한 잔 부탁해요."]], "orders": [{"type": "drink", "name": "게이트 라이트"}], "after": [["교대 전 휴게소 직원", "잘 마셨어요. 이제 퇴근하러 갑니다."]], "optionalSpecialSource": "market"});

day13Visits.sort((a,b)=>{const minutes=x=>{const [h,m]=x.time.split(":").map(Number);return (h<18?h+24:h)*60+m;};return minutes(a)-minutes(b);});

day15Visits.push({"who": "추천 지점 탐방객", "time": "19:10", "dialogue": [["추천 지점 탐방객", "안내 페이지에 올라온 새 메뉴들이 궁금해서 왔어요."], ["추천 지점 탐방객", "루비 라인 한 잔 주세요."]], "orders": [{"type": "drink", "name": "루비 라인"}], "after": [["추천 지점 탐방객", "다음에는 친구랑 같이 와봐야겠어요."]], "optionalSpecialSource": "custom"});

day15Visits.push({"who": "야간 철도 시설 관리원", "time": "22:05", "dialogue": [["야간 철도 시설 관리원", "야간 점검이 끝나면 뜨끈한 음식부터 생각나요."], ["야간 철도 시설 관리원", "가든 야채스프 한 그릇 부탁해요."]], "orders": [{"type": "food", "name": "가든 야채스프"}], "after": [["야간 철도 시설 관리원", "몸이 좀 풀리네요. 잘 먹었습니다."]], "optionalSpecialSource": "market"});

day15Visits.push({"who": "늦은 셔틀 환승객", "time": "00:20", "dialogue": [["늦은 셔틀 환승객", "환승 대기 시간이 길어서 여기까지 산책을 나왔어요."], ["늦은 셔틀 환승객", "프리즘 믹스 한 잔 주세요."]], "orders": [{"type": "drink", "name": "프리즘 믹스"}], "after": [["늦은 셔틀 환승객", "이제 셔틀 시간에 맞춰 가볼게요."]], "optionalSpecialSource": "custom"});

day15Visits.sort((a,b)=>{const minutes=x=>{const [h,m]=x.time.split(":").map(Number);return (h<18?h+24:h)*60+m;};return minutes(a)-minutes(b);});
